WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pb_r_bern'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '伯努利直观题', 'kp-pb-r-bern', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "独立重复试验（伯努利模型）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "N 次试验中刚好发生 K 次。必须乘以 C(N,K) 进行组合排位！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“投篮命中率 0.8。投 5 次，恰好命中 3 次的概率？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "很多人算出 0.8 × 0.8 × 0.8 × 0.2 × 0.2 就觉得完事了。错！这只代表了“前三次全中，后两次全不中”这一种特定排列。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "命中 3 次，可能是第 1,3,5 次中，也可能是第 2,3,4 次中。到底有几种排法？C(5,3) 种！"}]}, {"type": "katexBlock", "attrs": {"content": "P(X=k) = C_n^k \\times p^k \\times (1-p)^{n-k}"}}]}$$ AS jsonb), NULL, '伯努利直观题的核心考点与实战推导。', category_node.id, CAST('["数量关系", "概率问题", "伯努利直观题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pb_r_bern", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
